<style>
[hidden]{display:none!important}
.traffic-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.traffic-actions>*{margin:0!important}.traffic-form{display:grid;gap:14px;max-width:900px}.traffic-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.traffic-form label{display:grid;gap:6px;min-width:0}.traffic-form .c-input{width:100%;box-sizing:border-box;min-height:36px;font:inherit;color:var(--text-primary,#eee);background:var(--bg-input,#111827);border:1px solid var(--border-color,#475569);padding:8px;border-radius:4px}.traffic-form textarea{resize:vertical}.traffic-form .traffic-check{display:flex;align-items:flex-start;gap:8px}.traffic-table{max-width:100%;overflow-x:auto}.traffic-table table{min-width:620px;width:100%}.traffic-details{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:20px 0}.traffic-details dt{color:var(--text-secondary,#9ca3af);font-size:12px}.traffic-details dd{margin:5px 0 0;white-space:pre-wrap;overflow-wrap:anywhere}.traffic-events{padding-left:20px}.traffic-events li{margin:14px 0;overflow-wrap:anywhere}.traffic-events p{white-space:pre-wrap}.traffic-section{border-top:1px solid var(--border-color,#475569);padding-top:18px;margin-top:20px}.traffic-notice{color:var(--text-secondary,#9ca3af)}.cs-tabs{display:flex;gap:8px;flex-wrap:wrap}.cs-tabs .is-active{border-color:#3b82f6}.traffic-form button,.traffic-actions a{min-height:32px} @media(max-width:760px){.traffic-grid,.traffic-details{grid-template-columns:1fr}.traffic-form{max-width:100%}.c-page-header{flex-wrap:wrap;gap:12px}}
</style>
